import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BdWD-ld-.js";const u=JSON.parse('{"title":"2026-11-16 · Agent 核心研究与竞品动态","description":"审计 benchmark、恢复回执、企业授权、数字员工协作与协议互通；39 项事实观察、6 组研究分析。","frontmatter":{"title":"2026-11-16 · Agent 核心研究与竞品动态","description":"审计 benchmark、恢复回执、企业授权、数字员工协作与协议互通；39 项事实观察、6 组研究分析。"},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-11-16.md","filePath":"zh/runtime/daily-intelligence/2026-11-16.md","lastUpdated":1794794162000}'),n={name:"zh/runtime/daily-intelligence/2026-11-16.md"};function s(p,e,l,h,i,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_2026-11-16-·-agent-核心研究与竞品动态" tabindex="-1">2026-11-16 · Agent 核心研究与竞品动态 <a class="header-anchor" href="#_2026-11-16-·-agent-核心研究与竞品动态" aria-label="Permalink to &quot;2026-11-16 · Agent 核心研究与竞品动态&quot;">​</a></h1><p>本轮最重要的结论：<strong>数字员工治理需要把“授权谁做、执行到了哪里、成果由谁验收”串成可核对的链条。</strong> 赵越发布可复现审计榜单；Codex、Agents SDK、Paperclip 与 OpenHands 补齐恢复/回执边界；AG2 正式迁移 ACP 1.0 与用量口径；MCP/A2A 的新讨论强调独立效果证据与真实互通验证。这些是分层研究线索，不证明 CodeFlowMu 已有对应故障，也不构成本地实验或开发评审结论。</p><p>运行日期按 Asia/Shanghai 为 <strong>2026-11-16</strong>；执行起点/事件筛选上界 <strong>2026-11-16T01:07:24Z（09:07:24 北京时间）</strong>。最后成功记录为 <strong>2026-11-14T065509Z</strong>；11-15 无成功运行记录，本轮按各来源成功/未完基线补查，不补造 11-15 日报。以下发生日期及 Z 时间采用 <strong>UTC</strong>；状态为本轮实际读取时的快照，筛选上界之后的状态变化另记后续运行。</p><h2 id="事实观察" tabindex="-1">事实观察 <a class="header-anchor" href="#事实观察" aria-label="Permalink to &quot;事实观察&quot;">​</a></h2><h3 id="o1-·-赵越-审计方法进入可复现榜单" tabindex="-1">O1 · 赵越：审计方法进入可复现榜单 <a class="header-anchor" href="#o1-·-赵越-审计方法进入可复现榜单" aria-label="Permalink to &quot;O1 · 赵越：审计方法进入可复现榜单&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。auditable v0.4.0 已发行（06:22Z），提供 PRE/LIVE/POST 共 44 种方法、6 个固定数据与协议的 CatchBench 榜单，以及 golden 校验。Oracle 不参与排名；跳过、错误和未核对值不能冒充通过。规模控制模型在 SWEGym 超过两种 GRADE 依赖回归，在 Tau 则落后于其中一种，不能据此断言依赖图普遍占优。Apache-2.0；核心轻量，完整 benchmark 另需数据与可选依赖。赵越仍直接提交与发行；本地未复现。</p><p><a href="https://github.com/yzhao062/auditable/releases/tag/v0.4.0" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：如何在相同规模控制与跨数据集条件下比较 GRADE 的增益？</p><h3 id="o2-·-赵越-评审轮次与-worker-结果分开绑定" tabindex="-1">O2 · 赵越：评审轮次与 worker 结果分开绑定 <a class="header-anchor" href="#o2-·-赵越-评审轮次与-worker-结果分开绑定" aria-label="Permalink to &quot;O2 · 赵越：评审轮次与 worker 结果分开绑定&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。anywhere-agents 两项 main 提交已落地：其他轮次的 Gemini/Claude 评审不能被重新贴成当前轮次，失败退出 70 且不发布；Codex 最终消息写入新结果路径，保留 worker 自写工件与非零退出信号。退出 0 但无可用结果也失败，fallback 有长度上限。轮次标记检查不是语义正确性证明；未见本轮正式 Release。</p><p><a href="https://github.com/yzhao062/anywhere-agents/commit/db5707f837540785c22a26b109c658cd826457f6" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/yzhao062/anywhere-agents/commit/39525f4c96fdf83e4fb4b96e13cb44a8c0e6cb2e" target="_blank" rel="noreferrer">原始证据 2</a></p><p>值得互动：能否把评审轮次、工件摘要与任务版本共同绑定，而非只验 marker？</p><h3 id="o3-·-codex-非交互执行接入远程-app-server" tabindex="-1">O3 · Codex：非交互执行接入远程 app-server <a class="header-anchor" href="#o3-·-codex-非交互执行接入远程-app-server" aria-label="Permalink to &quot;O3 · Codex：非交互执行接入远程 app-server&quot;">​</a></h3><p>发生日期: 2026-11-16 UTC。#61707 已合入（00:02Z）：codex exec --remote 连接现有 app-server，可新建或恢复指定线程，保留远端配置与凭证边界；活动线程、冲突配置及完成前断连有明确拒绝/错误。这里是远程控制与会话接续，不等于跨主机搬迁活进程；未核实进入正式安装包。</p><p><a href="https://github.com/openai/codex/pull/61707" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：远程线程恢复时，客户端如何查询未确认执行的 authoritative receipt？</p><h3 id="o4-·-codex-预算约束覆盖整棵-agent-树与重试成本" tabindex="-1">O4 · Codex：预算约束覆盖整棵 Agent 树与重试成本 <a class="header-anchor" href="#o4-·-codex-预算约束覆盖整棵-agent-树与重试成本" aria-label="Permalink to &quot;O4 · Codex：预算约束覆盖整棵 Agent 树与重试成本&quot;">​</a></h3><p>发生日期: 2026-11-14–15 UTC。#61578/#61582 已合入：等待审批、执行权或 lifecycle 后，MCP/模型/工具开始前再次检查共享预算，耗尽后不再自动唤醒新工作。#61580 将同步 MCP 后置 hook 的成本另行记账，非法计费不能触发推理重试；#61587 为模型请求提供跨重试稳定 request_id 与 attempt。#61581 用中性中断标记。已消费结果保留，预算门不等于撤销已发生效果；均未核实发行。</p><p><a href="https://github.com/openai/codex/pull/61578" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/openai/codex/pull/61582" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/openai/codex/pull/61580" target="_blank" rel="noreferrer">原始证据 3</a> · <a href="https://github.com/openai/codex/pull/61587" target="_blank" rel="noreferrer">原始证据 4</a> · <a href="https://github.com/openai/codex/pull/61581" target="_blank" rel="noreferrer">原始证据 5</a></p><p>值得互动：预算等待后重验与已发生效果的结算如何在子 Agent 树中对齐？</p><h3 id="o5-·-codex-环境权限描述开始分域" tabindex="-1">O5 · Codex：环境权限描述开始分域 <a class="header-anchor" href="#o5-·-codex-环境权限描述开始分域" aria-label="Permalink to &quot;O5 · Codex：环境权限描述开始分域&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。#61494 已合入：按 environment ID 描述文件系统/网络权限，撤下失效描述，共享要求单列；实验开关默认关闭。这是模型上下文与权限说明的准确性改进，不能当成新增强制执行边界或已默认启用能力。</p><p><a href="https://github.com/openai/codex/pull/61494" target="_blank" rel="noreferrer">原始证据 1</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o6-·-codex-cloud-恢复失败需要可见结算" tabindex="-1">O6 · Codex：Cloud 恢复失败需要可见结算 <a class="header-anchor" href="#o6-·-codex-cloud-恢复失败需要可见结算" aria-label="Permalink to &quot;O6 · Codex：Cloud 恢复失败需要可见结算&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#61599 已合入：区分会话缺失、访问拒绝、登录身份变化/过期及重连耗尽；废弃的线程/条目读取会取消。研究价值是把身份失效和临时网络故障分开，避免界面继续显示可恢复；未核实正式发行。</p><p><a href="https://github.com/openai/codex/pull/61599" target="_blank" rel="noreferrer">原始证据 1</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o7-·-agents-python-待审批补丁跨-checkpoint-仍需重新批准" tabindex="-1">O7 · Agents Python：待审批补丁跨 checkpoint 仍需重新批准 <a class="header-anchor" href="#o7-·-agents-python-待审批补丁跨-checkpoint-仍需重新批准" aria-label="Permalink to &quot;O7 · Agents Python：待审批补丁跨 checkpoint 仍需重新批准&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。原生预览路径 #6008/#6003 已合入：停止并等待并发 dispatch 后才快照准确 pending ApplyPatch 集合，保留已完成 sibling 的输出；恢复后再次审批，校验当前工具声明及 action/owner，审批前不触发生命周期回调。不是复用旧许可自动执行；未证实进入稳定 Python SDK 发行。</p><p><a href="https://github.com/openai/openai-agents-python/pull/6008" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/openai/openai-agents-python/pull/6003" target="_blank" rel="noreferrer">原始证据 2</a></p><p>值得互动：恢复时工具声明或 owner 改变，怎样给出可追溯的重新审批原因？</p><h3 id="o8-·-agents-原生-python-js-接受回执、进程退出与会话关闭分开" tabindex="-1">O8 · Agents 原生 Python/JS：接受回执、进程退出与会话关闭分开 <a class="header-anchor" href="#o8-·-agents-原生-python-js-接受回执、进程退出与会话关闭分开" aria-label="Permalink to &quot;O8 · Agents 原生 Python/JS：接受回执、进程退出与会话关闭分开&quot;">​</a></h3><p>发生日期: 2026-11-14–15 UTC。Python #5985/#5998/#6015/#6026 与 JS #2662 已合入：已接受的人工工具回复不因后续预算失败被改判未接收；取消需等待自己启动的远端命令退出，未确认就报告清理失败并退役连接，不能谎报已终止。JS 补齐 tool-search 事件及当前 sandbox/editor 归属检查。严格参数修正仍需审批；已发布 alpha7 的兼容限制有记录。均属原生预览合入；部分 hosted/Docker 验证待完成。</p><p><a href="https://github.com/openai/openai-agents-python/pull/5985" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/openai/openai-agents-python/pull/5998" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/openai/openai-agents-python/pull/6015" target="_blank" rel="noreferrer">原始证据 3</a> · <a href="https://github.com/openai/openai-agents-python/pull/6026" target="_blank" rel="noreferrer">原始证据 4</a> · <a href="https://github.com/openai/openai-agents-js/pull/2662" target="_blank" rel="noreferrer">原始证据 5</a></p><p>值得互动：未确认 Stop 与已接受工具回复分别应产生什么可重放回执？</p><h3 id="o9-·-paperclip-供应商发起的-turn-开始接入行为" tabindex="-1">O9 · Paperclip：供应商发起的 turn 开始接入行为 <a class="header-anchor" href="#o9-·-paperclip-供应商发起的-turn-开始接入行为" aria-label="Permalink to &quot;O9 · Paperclip：供应商发起的 turn 开始接入行为&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。#21612/#21456 已合入：controller 重启可恢复等待供应商发起 turn 的 checkpoint；native ACPX Claude 请求 runner 的 providerStartedTurns，使后台命令跨 turn 继续，不再误判 native_finalization_missing。相较 11-14 的契约观察，这是新增行为，但范围限该原生适配路径。学习价值高、竞争风险高，维持主雷达；发行未核实。</p><p><a href="https://github.com/paperclipai/paperclip/pull/21612" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/21456" target="_blank" rel="noreferrer">原始证据 2</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o10-·-paperclip-工具结果已记录不代表已交付" tabindex="-1">O10 · Paperclip：工具结果已记录不代表已交付 <a class="header-anchor" href="#o10-·-paperclip-工具结果已记录不代表已交付" aria-label="Permalink to &quot;O10 · Paperclip：工具结果已记录不代表已交付&quot;">​</a></h3><p>发生日期: 2026-11-14–15 UTC。#21490 已合入：REST 200 的 operationId 被误当语义封包，结果未到 OpenCode，造成约 290 秒 pending 与后续 attach 阻塞；修复结算记录结果和关闭 turn 的遗留调用。#21786 又将重启 detach 间未 dispatch 的输入留给下一 controller，而非写成终局失败。学习价值高、竞争风险高，主雷达不变；不能据修复宣称端到端 exactly-once。</p><p><a href="https://github.com/paperclipai/paperclip/pull/21490" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/21786" target="_blank" rel="noreferrer">原始证据 2</a></p><p>值得互动：如何区分记录成功、客户端送达与效果完成，避免恢复时重复执行？</p><h3 id="o11-·-paperclip-部署重叠与降级恢复要有终止条件" tabindex="-1">O11 · Paperclip：部署重叠与降级恢复要有终止条件 <a class="header-anchor" href="#o11-·-paperclip-部署重叠与降级恢复要有终止条件" aria-label="Permalink to &quot;O11 · Paperclip：部署重叠与降级恢复要有终止条件&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#21697 已合入：旧 owner 仍活着时等待其释放，再接续 warm session；修复此前 release-swap 2/8 失败。#21541 对永久丢失文件允许新工作区继续，不声称恢复旧文件；#21734 对重复拒绝工具调用设置终止/新续接条件。学习价值高、竞争风险高；这些是不同损失等级的恢复策略，上游结果不是本地通过。</p><p><a href="https://github.com/paperclipai/paperclip/pull/21697" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/paperclipai/paperclip/pull/21541" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/paperclipai/paperclip/pull/21734" target="_blank" rel="noreferrer">原始证据 3</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o12-·-paperclip-公平连接准入不是硬上限" tabindex="-1">O12 · Paperclip：公平连接准入不是硬上限 <a class="header-anchor" href="#o12-·-paperclip-公平连接准入不是硬上限" aria-label="Permalink to &quot;O12 · Paperclip：公平连接准入不是硬上限&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#21693 已合入：专用数据库连接采用 FIFO、默认 24 的准入；嵌套事务等绕开排队防死锁，等待超时后可越限。上游 burst 峰值 48，不能宣传为连接数严格封顶 24。学习价值高、竞争风险高；值得比较恢复风暴下的公平性、延迟与总连接预算。</p><p><a href="https://github.com/paperclipai/paperclip/pull/21693" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：恢复 burst 下软准入越限的公平性和总连接预算如何量测？</p><h3 id="o13-·-paperclip-真实-agent-扩容工具已合入-千-agent-尚未实测" tabindex="-1">O13 · Paperclip：真实 Agent 扩容工具已合入，千 Agent 尚未实测 <a class="header-anchor" href="#o13-·-paperclip-真实-agent-扩容工具已合入-千-agent-尚未实测" aria-label="Permalink to &quot;O13 · Paperclip：真实 Agent 扩容工具已合入，千 Agent 尚未实测&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#21695 已合入，提供 10/50/100/200/500/1000 阶梯，测排队、首次活动、延迟和费用，缺测标 not measured，首个失败即停并清理。PR 明说未对真实实例跑该工具，超过 50 的既有材料仍是模型估算。学习价值高，竞争风险高但千 Agent 成熟度证据仍不足；不升级为已验证规模优势。</p><p><a href="https://github.com/paperclipai/paperclip/pull/21695" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：首个真实实例阶梯结果能否公开缺测、失败与清理证据？</p><h3 id="o14-·-openhands-会话-fork-必须保留可解密的凭证归属" tabindex="-1">O14 · OpenHands：会话 fork 必须保留可解密的凭证归属 <a class="header-anchor" href="#o14-·-openhands-会话-fork-必须保留可解密的凭证归属" aria-label="Permalink to &quot;O14 · OpenHands：会话 fork 必须保留可解密的凭证归属&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#5765 已合入：复制源 cipher 与深拷贝 secrets registry，继续使用正常加密持久化，使 fork 重启后能恢复凭证。它修复状态继承，不构成允许跨用户共享 secret 的新授权。上游有回归测试，本地未测试；发行未核实。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/5765" target="_blank" rel="noreferrer">原始证据 1</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o15-·-openhands-pid-重用不能继续证明租约-owner-活着" tabindex="-1">O15 · OpenHands：PID 重用不能继续证明租约 owner 活着 <a class="header-anchor" href="#o15-·-openhands-pid-重用不能继续证明租约-owner-活着" aria-label="Permalink to &quot;O15 · OpenHands：PID 重用不能继续证明租约 owner 活着&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#6827 已合入：本机 /proc 的进程起始时间与 PID 一起识别 owner，僵尸/死亡进程可回收。其他主机、旧记录、缺少 /proc 或同一活进程仍受原 TTL 限制，不是任意强制抢租约。研究价值在 ownership 的证据边界，属 Runtime 而非直接 FCoP 内核需求。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/6827" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：跨 host 无 /proc 时，owner 证明与 TTL 退化边界如何呈现？</p><h3 id="o16-·-openhands-回复必须对应本次-run" tabindex="-1">O16 · OpenHands：回复必须对应本次 run <a class="header-anchor" href="#o16-·-openhands-回复必须对应本次-run" aria-label="Permalink to &quot;O16 · OpenHands：回复必须对应本次 run&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。#6843 已合入：gateway 在已暂停/错误的 conversation 上运行成功后，曾读到旧状态而返回 409/500，诱发用户重试和重复任务；现在等待自己启动的 live run，自身失败仍正确报错。价值是避免把历史状态当作本次回执；未核实正式发行。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/6843" target="_blank" rel="noreferrer">原始证据 1</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o17-·-openhands-超时总预算与快速瞬态失败分开" tabindex="-1">O17 · OpenHands：超时总预算与快速瞬态失败分开 <a class="header-anchor" href="#o17-·-openhands-超时总预算与快速瞬态失败分开" aria-label="Permalink to &quot;O17 · OpenHands：超时总预算与快速瞬态失败分开&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#6822/#6866 均已合入：反复长超时的总预算约为单次 timeout 的两倍；后续修正保留快速瞬态超时的正常重试，避免最后一次很快失败也被误写为硬耗尽。配置/Settings 类问题会明确指出。不能只读前一 PR 就说所有 timeout 都立即终止；未核实发行。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/6822" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6866" target="_blank" rel="noreferrer">原始证据 2</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o18-·-openhands-公网-mcp-oauth-与-app-同意分层" tabindex="-1">O18 · OpenHands：公网 MCP OAuth 与 App 同意分层 <a class="header-anchor" href="#o18-·-openhands-公网-mcp-oauth-与-app-同意分层" aria-label="Permalink to &quot;O18 · OpenHands：公网 MCP OAuth 与 App 同意分层&quot;">​</a></h3><p>发生日期: 2026-11-14–15 UTC。SDK #6221 已合入公网 callback，单次 state、过期/重放拒绝及部署前缀；预注册客户端的回调限制仍需配置。核心 #18572 已合入：仅当前 App revision、已选 secret 的同意可触发托管启用，撤回则停；安装/挂载本身不启动。公网认证 iframe 链路仍未验证。两项不能拼成已验证企业端到端授权。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/6221" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/OpenHands/OpenHands/pull/18572" target="_blank" rel="noreferrer">原始证据 2</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o19-·-openhands-windows-终端恢复不重放失败动作" tabindex="-1">O19 · OpenHands：Windows 终端恢复不重放失败动作 <a class="header-anchor" href="#o19-·-openhands-windows-终端恢复不重放失败动作" aria-label="Permalink to &quot;O19 · OpenHands：Windows 终端恢复不重放失败动作&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#4962 已合入：处理 PowerShell 完成标记、终止错误、私有控制台 Ctrl-C 与有界子进程清理；终端死亡可重建，但不自动重放失败动作，安装包不再假定系统有 Python。上游 Windows 测试 233 通过、196 跳过，不是本机交付验收。与数字员工 Windows 宿主适配直接相关。</p><p><a href="https://github.com/OpenHands/software-agent-sdk/pull/4962" target="_blank" rel="noreferrer">原始证据 1</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o20-·-browser-use-截图验收已发行-证据绑定修复仍开放" tabindex="-1">O20 · browser-use：截图验收已发行，证据绑定修复仍开放 <a class="header-anchor" href="#o20-·-browser-use-截图验收已发行-证据绑定修复仍开放" aria-label="Permalink to &quot;O20 · browser-use：截图验收已发行，证据绑定修复仍开放&quot;">​</a></h3><p>发生日期: 2026-11-14–16 UTC。1.0.5/1.0.6 已发行：#6403 给同模型 judge 加近期/最终截图，#6418 要求 gotcha 据实际 trace，缺证据不写推断，可为零。#6411 仍 OPEN，拟修多会话时最终截图绑错页面。截图未脱敏；13 次上游运行中 gotcha 检出改善不等于任务成功率提高；后续 trace 规则只有脚本测试、无付费模型评估。该 judge 不是独立验收。</p><p><a href="https://github.com/browser-use/browser-use/releases/tag/1.0.6" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/browser-use/browser-use/pull/6403" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/browser-use/browser-use/pull/6418" target="_blank" rel="noreferrer">原始证据 3</a> · <a href="https://github.com/browser-use/browser-use/pull/6411" target="_blank" rel="noreferrer">原始证据 4</a></p><p>值得互动：验收截图能否同时绑定 session、任务版本和独立采集者？</p><h3 id="o21-·-browser-use-默认模型变化带来真实预算迁移" tabindex="-1">O21 · browser-use：默认模型变化带来真实预算迁移 <a class="header-anchor" href="#o21-·-browser-use-默认模型变化带来真实预算迁移" aria-label="Permalink to &quot;O21 · browser-use：默认模型变化带来真实预算迁移&quot;">​</a></h3><p>发生日期: 2026-11-16 UTC。1.0.6 已发行（00:51Z），#6430 将默认 bu-fast 换为高推理 bu-4.0。发行说明列输入/输出单价由 0.12/0.60 变 1.80/9 美元每百万 token，即单价 15 倍；单个样例费用不代表所有任务倍率。显式指定 bu-fast 可保留原选择。数字员工长期成本需要固定模型、推理档与价格版本。</p><p><a href="https://github.com/browser-use/browser-use/releases/tag/1.0.6" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/browser-use/browser-use/pull/6430" target="_blank" rel="noreferrer">原始证据 2</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o22-·-browser-use-治理五件套都还是草稿" tabindex="-1">O22 · browser-use：治理五件套都还是草稿 <a class="header-anchor" href="#o22-·-browser-use-治理五件套都还是草稿" aria-label="Permalink to &quot;O22 · browser-use：治理五件套都还是草稿&quot;">​</a></h3><p>发生日期: 2026-11-15–16 UTC。#6414/#6416/#6415/#6421/#6417 均 OPEN+DRAFT：动作前后 hook、效果处审批、脱敏哈希链、严格域与最小登录资料。限制明确：cell hook 不等于所有效果边界；日志后置失败可只记录而返回结果；链完整不证明没有漏记；strict_domains 不覆盖 WebSocket/WebRTC/WebTransport、原始 socket 等路径。适合研究方案，不能写成已发布治理能力。</p><p><a href="https://github.com/browser-use/browser-use/pull/6414" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/browser-use/browser-use/pull/6416" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/browser-use/browser-use/pull/6415" target="_blank" rel="noreferrer">原始证据 3</a> · <a href="https://github.com/browser-use/browser-use/pull/6421" target="_blank" rel="noreferrer">原始证据 4</a> · <a href="https://github.com/browser-use/browser-use/pull/6417" target="_blank" rel="noreferrer">原始证据 5</a></p><p>值得互动：路由覆盖清单和外部完整性锚点怎样证明遗漏，而不只校验链？</p><h3 id="o23-·-adk-自适应团队编排仍是实验提案" tabindex="-1">O23 · ADK：自适应团队编排仍是实验提案 <a class="header-anchor" href="#o23-·-adk-自适应团队编排仍是实验提案" aria-label="Permalink to &quot;O23 · ADK：自适应团队编排仍是实验提案&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#8174 OPEN、非草稿：普通 Python workflow 驱动 specialist roster、TaskPlan、RoundAssessment、停滞/重规划/轮次上限，可选人工审计划；session 内 snapshot 与稳定调用 ID 支持恢复，新的用户消息重置。只有 mock/功能测试，未做 hosted 模型或人工端到端验收。适合研究数字员工分工、停滞接替与协调成本，不是已发行成熟团队能力。</p><p><a href="https://github.com/google/adk-python/pull/8174" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：重规划预算、人审次数与迟到 specialist 结果是否共同计入协调成本？</p><h3 id="o24-·-adk-跨-mcp-连接接续需要应用身份边界" tabindex="-1">O24 · ADK：跨 MCP 连接接续需要应用身份边界 <a class="header-anchor" href="#o24-·-adk-跨-mcp-连接接续需要应用身份边界" aria-label="Permalink to &quot;O24 · ADK：跨 MCP 连接接续需要应用身份边界&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#8164 OPEN、非草稿：可显式传 session_id 跨 transport 延续会话，unknown ID 新建；session 生命周期由宿主管理。提案明确 ID 只是句柄，知道 ID 的调用方可加入，不能把 session_id 当授权凭证。与 FCoP 互操作有关的是会话关联，身份/租户校验仍须适配层另行建立。</p><p><a href="https://github.com/google/adk-python/pull/8164" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：session_id 如何绑定已认证主体与 tenant，避免知道句柄即可加入？</p><h3 id="o25-·-crewai-hook-故障拒绝执行仍未合入" tabindex="-1">O25 · CrewAI：hook 故障拒绝执行仍未合入 <a class="header-anchor" href="#o25-·-crewai-hook-故障拒绝执行仍未合入" aria-label="Permalink to &quot;O25 · CrewAI：hook 故障拒绝执行仍未合入&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#9465 OPEN、非草稿：拟以 on_error=abort 让前/后工具 hook 异常抛 HookAborted，后置失败可阻止未经处理结果进入模型；默认 fail-open 不变。有针对性测试，不能报告为框架已经 fail-closed。值得问清后置拒绝与外部效果已发生时如何结算。</p><p><a href="https://github.com/crewAIInc/crewAI/pull/9465" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：post-hook 拒绝时外部效果已发生，状态如何诚实结算？</p><h3 id="o26-·-orkas-安装升级与诊断日志收紧边界" tabindex="-1">O26 · Orkas：安装升级与诊断日志收紧边界 <a class="header-anchor" href="#o26-·-orkas-安装升级与诊断日志收紧边界" aria-label="Permalink to &quot;O26 · Orkas：安装升级与诊断日志收紧边界&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#220/#219 已合入：升级的复制/删除按真实物理路径检查托管文件链接及祖先，配合原子激活/重试；日志补齐转义、截断凭证的脱敏边界。上游测试不等于 Windows 完整安装验收，也不证明所有日志均无 secret。学习价值高，竞争风险中，维持主雷达，作为可交付数字员工的升级/诊断研究线索。</p><p><a href="https://github.com/Orkas-AI/Orkas/pull/220" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/Orkas-AI/Orkas/pull/219" target="_blank" rel="noreferrer">原始证据 2</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o27-·-paradev-手机可发起跨电脑工作区搬迁" tabindex="-1">O27 · Paradev：手机可发起跨电脑工作区搬迁 <a class="header-anchor" href="#o27-·-paradev-手机可发起跨电脑工作区搬迁" aria-label="Permalink to &quot;O27 · Paradev：手机可发起跨电脑工作区搬迁&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。原 Superset 仓库跳转至 ParadevAI/Paradev，保留来源归属。#9612/#9732 已合入：手机提交 durable move ID，任务归源 host，即使手机关闭也可继续；桌面可经 roster/relay 将另一台电脑的 workspace 搬到云端。受功能开关及源/目标环境约束，真实多宿主手工链路未验收。MIT；学习高、竞争风险高，维持主雷达并提高手机操作端关注，不宣称活进程无损迁移。</p><p><a href="https://github.com/ParadevAI/Paradev/pull/9612" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/ParadevAI/Paradev/pull/9732" target="_blank" rel="noreferrer">原始证据 2</a></p><p>值得互动：手机断线与源 host 失联时，move ID 的终局查询/取消契约是什么？</p><h3 id="o28-·-paradev-子-agent-后台运行与对话继续分开" tabindex="-1">O28 · Paradev：子 Agent 后台运行与对话继续分开 <a class="header-anchor" href="#o28-·-paradev-子-agent-后台运行与对话继续分开" aria-label="Permalink to &quot;O28 · Paradev：子 Agent 后台运行与对话继续分开&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。#9733 已合入：后台子 Agent 不再阻塞主对话，新消息可继续，迟到子结果接到最新 turn；前台任务仍排队。该实现固定 v1 协议，因 v2 steer 测试曾出现约 48 秒重复回复，不能把升级协议视为自动进步。学习高、竞争风险高，主雷达不变；需研究迟到成果的版本归属。</p><p><a href="https://github.com/ParadevAI/Paradev/pull/9733" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：迟到子成果如何避免被错误挂到已经改计划的新 turn？</p><h3 id="o29-·-orca-手机控制回收与睡眠恢复仍需状态证据" tabindex="-1">O29 · Orca：手机控制回收与睡眠恢复仍需状态证据 <a class="header-anchor" href="#o29-·-orca-手机控制回收与睡眠恢复仍需状态证据" aria-label="Permalink to &quot;O29 · Orca：手机控制回收与睡眠恢复仍需状态证据&quot;">​</a></h3><p>发生日期: 2026-11-15–16 UTC。#42785/#42864 已合入：Take back all 同时回收手机控制的浏览器与终端；另修 Codex pane 唤醒再睡眠时旧退出事件误删保存 session，仅在正确 spawn 接替时遗忘旧退出。后者上游未跑完整依赖/构建/测试，不能视作 Windows 验收通过。学习高、竞争风险中高，保留第二圈并提高人工接管关注。 另有 v1.4.259 于 11-14 21:20Z 正式发行，加入工作区清理控制和可查看实时步骤/最终答案的子任务视图；不能因此把之后的上述 PR 当作该版已包含。</p><p><a href="https://github.com/stablyai/orca/pull/42785" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/stablyai/orca/pull/42864" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/stablyai/orca/releases/tag/v1.4.259" target="_blank" rel="noreferrer">原始证据 3</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o30-·-agentlas-四层记忆归属带来真实迁移约束" tabindex="-1">O30 · Agentlas：四层记忆归属带来真实迁移约束 <a class="header-anchor" href="#o30-·-agentlas-四层记忆归属带来真实迁移约束" aria-label="Permalink to &quot;O30 · Agentlas：四层记忆归属带来真实迁移约束&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。os-v1.2.98 已发行（13:42Z）：personal/agent/project/session 四层记忆按 owner 召回/遗忘，项目用唯一 ID，未完成遗忘继续携带，读不全必须说明；session-end hook 只记录、不自启模型。转换仅由 Desktop 一次确认，需先升级引擎；schema2 旧引擎会停用记忆。Apache-2.0；学习高、风险中，维持第二圈并提高记忆治理关注；本地未安装，部分 host/Windows session 未验。</p><p><a href="https://github.com/agentlas-ai/Agentlas-OS/releases/tag/os-v1.2.98" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：跨 owner 遗忘如何验证完成，部分读取如何与真实无记忆区分？</p><h3 id="o31-·-vibe-kanban-新安装交付不等于商业复活" tabindex="-1">O31 · Vibe Kanban：新安装交付不等于商业复活 <a class="header-anchor" href="#o31-·-vibe-kanban-新安装交付不等于商业复活" aria-label="Permalink to &quot;O31 · Vibe Kanban：新安装交付不等于商业复活&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。v0.1.46.1794744340 已发行（13:16Z），把此前观察的 ACP 注册与审批桥修复带入 Release，调整 Codex 固定版本以恢复有效 macOS 签名，并关闭使用分析/崩溃上报。新增点是正式交付，不重复记旧 PR 为新功能。学习中、当前竞争风险低，仍作为 sunset 后维护/商业失败样本低频跟踪，未见足够证据推翻该定位。</p><p><a href="https://github.com/BloopAI/vibe-kanban/releases/tag/v0.1.46.1794744340" target="_blank" rel="noreferrer">原始证据 1</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h3 id="o32-·-mcp-审批证据与执行效果正在拆开讨论" tabindex="-1">O32 · MCP：审批证据与执行效果正在拆开讨论 <a class="header-anchor" href="#o32-·-mcp-审批证据与执行效果正在拆开讨论" aria-label="Permalink to &quot;O32 · MCP：审批证据与执行效果正在拆开讨论&quot;">​</a></h3><p>发生日期: 2026-11-15–16 UTC。SEP #2848 仍 OPEN+DRAFT。本轮新增是评论讨论，而不是新合入协议：提议精确命名 call digest，区分决策、效果与路径覆盖；审批不能把 outcome-unknown 变成已执行。评论给出哈希链截短仍可通过的反例，要求外部完整性锚点及独立效果观察；另有 OAC 参与者说明其 receipt 仍是执行者自述。都是提案/上游主张，本地未复现，官方 SDK 参考实现前提尚未满足。</p><p><a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2848#issuecomment-6887019800" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2848#issuecomment-6888074338" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2848#issuecomment-6903646262" target="_blank" rel="noreferrer">原始证据 3</a></p><p>值得互动：用同一调用的两种 canonical digest 与一次决策两次效果做互通负例？</p><h3 id="o33-·-a2a-扩展-纠正独立实现证据-增加混合故障向量" tabindex="-1">O33 · A2A 扩展：纠正独立实现证据，增加混合故障向量 <a class="header-anchor" href="#o33-·-a2a-扩展-纠正独立实现证据-增加混合故障向量" aria-label="Permalink to &quot;O33 · A2A 扩展：纠正独立实现证据，增加混合故障向量&quot;">​</a></h3><p>发生日期: 2026-11-14–15 UTC。A2A #2028 仍 OPEN；关联第三方 VAID #176 已合入（11-15 20:19Z），增加 15–18 四个向量，签名无效先判 INAUTHENTIC，签名有效但链不全判 UNVERIFIABLE；缺少可选 VAID 不自动判拒绝。README 纠正把复跑参考实现误称独立实现，真正独立证据仅覆盖 01–06。上游参考实现 18/18 不是两套独立实现全量互通，更不是 A2A 核心已接纳扩展。</p><p><a href="https://github.com/a2aproject/A2A/issues/2028#issuecomment-6896207423" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/solara-associates/vaid/pull/176" target="_blank" rel="noreferrer">原始证据 2</a></p><p>值得互动：独立实现能否覆盖新混合故障向量，并明确与参考复跑的证据差别？</p><h3 id="o34-·-mcp-工具-schema-缓存也有升级兼容契约" tabindex="-1">O34 · MCP：工具 schema 缓存也有升级兼容契约 <a class="header-anchor" href="#o34-·-mcp-工具-schema-缓存也有升级兼容契约" aria-label="Permalink to &quot;O34 · MCP：工具 schema 缓存也有升级兼容契约&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#3554 新建且 OPEN：作者报告服务端删去原 required 字段后，Claude Code/ChatGPT 缓存旧 outputSchema 而拒绝新结果；list_changed 不能消除刷新前竞态。建议兼容性增加可选字段、替换时保留旧字段。它是用户问题与非规范说明建议，未证实所有客户端、未成为规范；值得纳入长期运行员工的工具升级研究。</p><p><a href="https://github.com/modelcontextprotocol/modelcontextprotocol/issues/3554" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：schema 版本/摘要是否应随结果返回以区分升级竞态与服务端错误？</p><h3 id="o35-·-mcp-单一-issuer-不代表经过验证的凭证去向" tabindex="-1">O35 · MCP：单一 issuer 不代表经过验证的凭证去向 <a class="header-anchor" href="#o35-·-mcp-单一-issuer-不代表经过验证的凭证去向" aria-label="Permalink to &quot;O35 · MCP：单一 issuer 不代表经过验证的凭证去向&quot;">​</a></h3><p>发生日期: 2026-11-14 UTC。Python SDK #3850 仍 OPEN，本轮新讨论纠正 issuer 参数已存在并先于 token 请求校验；争议在未指定 issuer 时凭证跟随资源端声明的 endpoint。拒绝多授权服务器只解决选择歧义，不解决单服务器来源信任。涉及 FastMCP 版本与 SDK main，不能泛化成所有 MCP 都泄漏凭证；修复/回移与默认路径文档仍待处理。</p><p><a href="https://github.com/modelcontextprotocol/python-sdk/issues/3850#issuecomment-6877514411" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/modelcontextprotocol/python-sdk/issues/3850#issuecomment-6881273787" target="_blank" rel="noreferrer">原始证据 2</a></p><p>值得互动：单 issuer、无 issuer 的负例及回移文档能否一起保留？</p><h3 id="o36-·-langfuse-web-会话与-api-授权拟统一到-policy" tabindex="-1">O36 · Langfuse：Web 会话与 API 授权拟统一到 policy <a class="header-anchor" href="#o36-·-langfuse-web-会话与-api-授权拟统一到-policy" aria-label="Permalink to &quot;O36 · Langfuse：Web 会话与 API 授权拟统一到 policy&quot;">​</a></h3><p>发生日期: 2026-11-14–16 UTC。#20235 OPEN、非草稿，拟使 Web/tRPC 与公共 API 共用 policy 判定，审计记录 role ID，并以生产各 region 的角色漂移检查无结果作为合入前提。代价包括每次 session 读取新增查询、policy 进入客户端 session、旧新审计角色格式并存；数据库与预览验收未全做。是企业治理迁移研究线索，不是已发布统一授权。</p><p><a href="https://github.com/langfuse/langfuse/pull/20235" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：角色迁移如何验证 UI/API 同判且撤权后旧 session 不保留权限？</p><h3 id="o37-·-swe-agent-完成工件与评测索引文件不能互相替代" tabindex="-1">O37 · SWE-agent：完成工件与评测索引文件不能互相替代 <a class="header-anchor" href="#o37-·-swe-agent-完成工件与评测索引文件不能互相替代" aria-label="Permalink to &quot;O37 · SWE-agent：完成工件与评测索引文件不能互相替代&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。#1642 OPEN、非草稿：拟从 trajectory 中明确 submission 重建缺失/截断 .pred，包含空 patch；临时文件完成后原子发布并保留权限/ACL，供并发评测读取。上游给出复现与 32 项测试，本地未验证，未合入。对数字员工价值在交付物已完成而派生登记丢失时的可核对恢复，不能靠退出码或目录存在判完成。</p><p><a href="https://github.com/SWE-agent/SWE-agent/pull/1642" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：派生预测索引重建如何绑定原任务 revision 与独立交付验收？</p><h3 id="o38-·-ag2-1-3-2-多问决策、用量口径与-acp-迁移一起发行" tabindex="-1">O38 · AG2 1.3.2：多问决策、用量口径与 ACP 迁移一起发行 <a class="header-anchor" href="#o38-·-ag2-1-3-2-多问决策、用量口径与-acp-迁移一起发行" aria-label="Permalink to &quot;O38 · AG2 1.3.2：多问决策、用量口径与 ACP 迁移一起发行&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。v1.3.2 已发行（16:37Z）：扁平 schema 可在一次请求问多个决策，复杂/缺 Question 的结构请求前拒绝；缓存读写计入整体 prompt、thinking 计入 completion，旧记录不重写，混合供应商预算可能更早触顶。ACP extra 改为 &gt;=1,&lt;2（不再支持 0.12），分离消息与最终答复，保留资源/工具结果结构，排队输入移到下一 turn，避免盖掉 final/client handoff。Python 3.15 虽获支持，Windows 缺编译器时 PyYAML 源码安装仍会失败。是已交付互操作与成本契约，未本地升级验证。</p><p><a href="https://github.com/ag2ai/ag2/releases/tag/v1.3.2" target="_blank" rel="noreferrer">原始证据 1</a></p><p>值得互动：历史与新 token 口径并存时，混合供应商预算如何避免重复算缓存？</p><h3 id="o39-·-langchain-供应商适配包加入网关并收紧-python-支持" tabindex="-1">O39 · LangChain：供应商适配包加入网关并收紧 Python 支持 <a class="header-anchor" href="#o39-·-langchain-供应商适配包加入网关并收紧-python-支持" aria-label="Permalink to &quot;O39 · LangChain：供应商适配包加入网关并收紧 Python 支持&quot;">​</a></h3><p>发生日期: 2026-11-15 UTC。langchain-xai 1.4.0、langchain-mistralai 1.2.0、langchain-groq 1.2.0 已发行，分别增加 LangSmith gateway 路由；发行说明同时移除这些 partner 包的 Python 3.10 支持，Mistral 包修 reasoning 流式行为。可作为多供应商数字员工接入/交付线索，不能据路由能力推定企业凭证隔离或审计完整性已成立；本地未验证迁移。</p><p><a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-xai%3D%3D1.4.0" target="_blank" rel="noreferrer">原始证据 1</a> · <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-mistralai%3D%3D1.2.0" target="_blank" rel="noreferrer">原始证据 2</a> · <a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-groq%3D%3D1.2.0" target="_blank" rel="noreferrer">原始证据 3</a></p><p>分类：资料留存/持续观察；本轮无需立即互动。</p><h2 id="研究分析" tabindex="-1">研究分析 <a class="header-anchor" href="#研究分析" aria-label="Permalink to &quot;研究分析&quot;">​</a></h2><h3 id="a1-·-优先实验-未知执行结果如何结算-而不是直接重试" tabindex="-1">A1 · 优先实验：未知执行结果如何结算，而不是直接重试 <a class="header-anchor" href="#a1-·-优先实验-未知执行结果如何结算-而不是直接重试" aria-label="Permalink to &quot;A1 · 优先实验：未知执行结果如何结算，而不是直接重试&quot;">​</a></h3><p>依据: <strong>O2</strong>、<strong>O7</strong>、<strong>O8</strong>、<strong>O9</strong>、<strong>O10</strong>、<strong>O11</strong>、<strong>O15</strong>、<strong>O16</strong>、<strong>O19</strong>、<strong>O37</strong>。</p><p>已有证据：多个独立项目都在区分请求已接受、动作已启动、结果已落盘、回复已送达与当前 owner；修复适用范围各异，不能合称已解决 exactly-once。待验证推断：CodeFlowMu 数字员工跨 PM/worker、宿主重启或换模型时，可能需要先查询可核对效果，再决定是否重试，但本轮未证明本地存在缺陷。实验候选：在隔离假工具中发出有 occurrence ID 的写操作，分别在‘接收后、效果后、回执前’断链/重启，再换 worker 恢复；用独立只读观察者核对效果次数、归属与最终交付。通过条件是效果不重复、未知不冒充失败/成功、迟到结果不能覆盖新版本、旧 owner 不能继续提交。代价包括持久回执、fence 与外部查询；不可查询效果只能保留 unknown。FCoP 先比较任务/工件/证据的关联语义，owner/lease/进程取消放 Runtime。归为实验候选，未执行。</p><h3 id="a2-·-优先实验-审计与验收本身也要能被反例推翻" tabindex="-1">A2 · 优先实验：审计与验收本身也要能被反例推翻 <a class="header-anchor" href="#a2-·-优先实验-审计与验收本身也要能被反例推翻" aria-label="Permalink to &quot;A2 · 优先实验：审计与验收本身也要能被反例推翻&quot;">​</a></h3><p>依据: <strong>O1</strong>、<strong>O2</strong>、<strong>O20</strong>、<strong>O22</strong>、<strong>O32</strong>、<strong>O33</strong>、<strong>O34</strong>、<strong>O37</strong>。</p><p>已有证据：golden/规模控制能检验方法是否真优，截图可能绑错会话，同模型 judge 不独立，哈希链不自证完整，复跑参考实现不等于独立实现。待验证推断：数字员工的完成判定应比较‘工件来自哪次任务/版本、谁批准、谁观察到效果’，不能只看通过标记。实验候选：固定 auditable 0.4.0 数据与方法，在可承受的榜单先复现 golden，再加入错会话截图、旧轮工件、缺尾日志、错误 schema、一次决策两次效果和执行者自证的负例；独立 evaluator 只能对有证据的问题作结论。衡量错误放行、未知比例、定位质量、费用及规模控制，保留 skipped/error。FCoP 的研究点是工件摘要、版本和证据引用的互操作，日志外部锚点由部署承担。全量图模型依赖较重，先选轻量部分；未安装、未跑分。归为实验候选。</p><h3 id="a3-·-值得学-审批是特定动作的授权-恢复后要重读动态条件" tabindex="-1">A3 · 值得学：审批是特定动作的授权，恢复后要重读动态条件 <a class="header-anchor" href="#a3-·-值得学-审批是特定动作的授权-恢复后要重读动态条件" aria-label="Permalink to &quot;A3 · 值得学：审批是特定动作的授权，恢复后要重读动态条件&quot;">​</a></h3><p>依据: <strong>O5</strong>、<strong>O7</strong>、<strong>O14</strong>、<strong>O18</strong>、<strong>O22</strong>、<strong>O24</strong>、<strong>O25</strong>、<strong>O32</strong>、<strong>O33</strong>、<strong>O35</strong>、<strong>O36</strong>。</p><p>已有证据：checkpoint 后重新批准、当前 revision 的 secret 同意、issuer 绑定及 Web/API policy 统一都在避免把旧上下文当新授权。待验证推断：岗位/委派只确定职责背景；真正执行还要绑定当前主体、工具、目标、参数与环境。实验候选：批准后分别更换 tenant、工具声明、App revision、issuer、文件目标或凭证，及审批期间重启，检查是否拒绝/重新审批；保留原有效正例，防止一律拒绝的假通过。FCoP 比较可携带的授权/证据引用和拒绝语义；密钥保管、路由覆盖和调用前执行点属适配/Runtime，企业 UI/API 同判属产品。适用代价是额外查询、失效策略与多版本兼容。browser-use/CrewAI 草稿只能读方案；Langfuse 未合入不能当可用产品。归为持续观察与实验候选，未验证。</p><h3 id="a4-·-值得体验-数字员工团队要把停滞、迟到成果和记忆归属放在一起" tabindex="-1">A4 · 值得体验：数字员工团队要把停滞、迟到成果和记忆归属放在一起 <a class="header-anchor" href="#a4-·-值得体验-数字员工团队要把停滞、迟到成果和记忆归属放在一起" aria-label="Permalink to &quot;A4 · 值得体验：数字员工团队要把停滞、迟到成果和记忆归属放在一起&quot;">​</a></h3><p>依据: <strong>O2</strong>、<strong>O23</strong>、<strong>O27</strong>、<strong>O28</strong>、<strong>O29</strong>、<strong>O30</strong>、<strong>O38</strong>。</p><p>已有证据：ADK 提出有界重规划，Paradev 允许子任务后台返回，Agentlas 已交付分层记忆；AG2 合并同一输入的多问决策，减少重复请求，但不能据此证明团队效率已提升。待验证推断：持续履职员工需要稳定岗位/项目身份，换人接替时应接续有版本的工作状态，避免个人记忆和项目经验互串。体验候选优先 Agentlas 独立记忆引擎（Apache-2.0）与 AG2 1.3.2；ADK 先读提案，Paradev 另作完整产品体验候选（MIT）。建议同名不同项目、两用户同岗位、迟到子结果、人工改计划、停滞循环等固定场景，量化交付正确率、协调 token、人工次数与遗忘完成率。成本是宿主兼容、迁移与身份映射；本轮均未安装。FCoP 关注任务/成果版本与交接表示，记忆引擎和调度不直接进入内核。归为体验/实验候选。</p><h3 id="a5-·-值得研究-预算、恢复吞吐与安装交付是同一条企业成本链" tabindex="-1">A5 · 值得研究：预算、恢复吞吐与安装交付是同一条企业成本链 <a class="header-anchor" href="#a5-·-值得研究-预算、恢复吞吐与安装交付是同一条企业成本链" aria-label="Permalink to &quot;A5 · 值得研究：预算、恢复吞吐与安装交付是同一条企业成本链&quot;">​</a></h3><p>依据: <strong>O4</strong>、<strong>O6</strong>、<strong>O12</strong>、<strong>O13</strong>、<strong>O17</strong>、<strong>O19</strong>、<strong>O21</strong>、<strong>O26</strong>、<strong>O31</strong>、<strong>O38</strong>、<strong>O39</strong>。</p><p>已有证据：Codex 把准入与计费分开，Paperclip 的 24 是软门且扩容工具未实跑，browser-use 默认模型单价改变，AG2 统一缓存/思考 token，Python 包支持变化会影响 Windows 安装。待验证推断：多员工同时恢复可能把连接、预算、审批和诊断成本一起放大。实验候选：小规模 5/20 worker 恢复阶梯，固定模型和单价版本，注入预算耗尽、慢连接、超时与升级失败；测 p95 接续/首活动时间、连接峰值、总费用、丢/重任务，缺测不填零。先测本地可承担规模，不照搬千 Agent 宣称。协议层比较 usage/状态事实表达；准入公平性、硬/软预算和依赖安装属于 Runtime/交付。Orkas 升级与 Vibe 签名交付值得资料留存；不据上游用例判断本地成熟度。</p><h3 id="a6-·-竞品与协议判断-手机是治理终端-互通要用版本化用例证明" tabindex="-1">A6 · 竞品与协议判断：手机是治理终端，互通要用版本化用例证明 <a class="header-anchor" href="#a6-·-竞品与协议判断-手机是治理终端-互通要用版本化用例证明" aria-label="Permalink to &quot;A6 · 竞品与协议判断：手机是治理终端，互通要用版本化用例证明&quot;">​</a></h3><p>依据: <strong>O3</strong>、<strong>O8</strong>、<strong>O9</strong>、<strong>O18</strong>、<strong>O24</strong>、<strong>O27</strong>、<strong>O28</strong>、<strong>O29</strong>、<strong>O31</strong>、<strong>O32</strong>、<strong>O33</strong>、<strong>O34</strong>、<strong>O38</strong>。</p><p>已有证据：Paradev durable move、Orca takeback 与 Codex remote 分别覆盖产品操作、控制权与远程执行；AG2 的 ACP1 破坏性迁移、Paradev 留在 v1 的反例说明同名协议不代表同能力。待验证推断：CodeFlowMu 手机端值得研究审批、证据查看、暂停/接管和断线后的任务查询，而不是缩小 PC 界面。FCoP 与 MCP 工具调用、ACP 宿主会话、A2A 跨 Agent 任务/委派扩展分层比较；VAID/OAC 属第三方方案，不是官方同层替代。实验候选是固定版本的开始/接收/暂停/取消/恢复/工件交付用例矩阵，比较 state、event、receipt、身份与证据丢失情况。Paperclip/Paradev 保持高风险主雷达；Orkas 主雷达、Orca/Agentlas 第二圈加深专项；Vibe 继续低频。没有本地实验，不能因此下开发派工。</p><h2 id="跨项目共振与处置" tabindex="-1">跨项目共振与处置 <a class="header-anchor" href="#跨项目共振与处置" aria-label="Permalink to &quot;跨项目共振与处置&quot;">​</a></h2><p>共振范围限本轮已读项目：恢复时需要区分“接受、执行、效果、交付”；治理要跨审批、凭证、记忆、产物与接管；benchmark、日志链和截图本身也需要负例。不能从多个相似修复推出普适结论。</p><p>优先保留 A1 未知结果结算、A2 独立验收两项实验候选；A3 动态授权重验为后续候选。A4 的 Agentlas/AG2/Paradev 是体验候选，未安装；A5 是小规模恢复测量候选；A6 是固定版本互操作用例研究。<strong>本轮本地实验 0、文章 0、开发评审 0、派工 0、对外评论 0</strong>。上述数字仅描述本轮监测阶段，不修改任何 Runtime 生命周期事实。互动技术议题已逐项记录，实际评论稿/回执只留本地，本轮未发评论或执行加星。</p><p>竞品判断汇总：Paperclip、Paradev 学习价值高/竞争风险高，维持主雷达；Orkas 学习高/风险中，维持主雷达；Orca 学习高/风险中高，Agentlas 学习高/风险中，均保留第二圈并深化专项；Vibe 学习中/风险低，仍低频跟踪 sunset 后交付。无本地测评，不将主张或功能存在当作企业成熟度。</p><h2 id="双源核查与覆盖说明" tabindex="-1">双源核查与覆盖说明 <a class="header-anchor" href="#双源核查与覆盖说明" aria-label="Permalink to &quot;双源核查与覆盖说明&quot;">​</a></h2><ul><li>每轮先通过已连接 GitHub 工具读取 latest main 的 Registry，本轮 <strong>47 位研究者</strong>；研究者是主体，仓库为证据入口。保留手册全部指定项目与竞品，88 个原始仓库入口执行 commits/issues/releases 共 264 个首轮查询；180 个查询窗口完整、78 个分页未完、6 个不可访问/重定向，另做 5 个正确补页/跳转查询及选定 PR/Issue/评论/文档深读。完整查询只说明该 API/时间窗，不等于整个来源所有渠道核查完毕。</li><li>Paperclip 与 Orca commits 各再读第 2 页仍满页，保留待查窗口，不推进完整基线；多个 Issue/Release 页满页也保留待查。Superset 原入口重定向，已核验实际 Paradev 原始仓库的近期事件，但不冒充旧入口全部历史空档已补完。TSA 三类 API 404，保留不可访问；不推断项目停运。</li><li>6 位新增治理/验证对象的指定 GitHub 入口均纳入查询；Mansura Habiba 的 bulbasaur-skill-cli 仍只作相关项目，不称 AGENTSAFE 官方 Artifact；其余作者/论文关系按治理边界文档处理。赵越的补充项目保留原仓库归属，不把相关来源自动标作论文官方实现。赵越、Paperclip 的 nickyleach/cryppadotta、OpenHands 的 neubig/enyst 在所读提交/PR 中仍直接参与；未对所有项目维护者做穷尽身份审计。</li><li>非 GitHub 来源分别核查 <a href="https://prod.cursor.com/en-US/changelog" target="_blank" rel="noreferrer">Cursor 官方 changelog</a>、<a href="https://www.anthropic.com/engineering" target="_blank" rel="noreferrer">Anthropic engineering</a>、<a href="https://www.langchain.com/blog" target="_blank" rel="noreferrer">LangChain 官方博客</a>、<a href="https://docs.ag2.ai/docs/blog" target="_blank" rel="noreferrer">AG2 博客</a>、<a href="https://yzhao062.github.io/" target="_blank" rel="noreferrer">赵越主页</a>，及 Kaptein、Agrawal、de Witt、Shaokun Zhang、Haoyu Wang 的已确认主页。未核实到足够证据纳入本窗口的全新非 GitHub 事件；已有 11-13/更早材料按旧报/历史线索处理。DART（9-30）、SafeClaw-R（3-28）不冒充今日新论文。部分 X 检索无可确认新项，不等于穷尽 47 人账号/回复；Mansura 独立社交入口未完整核查。</li><li>GitHub 一手事实可独立支撑工程观察；不能把两个 GitHub 链接算两种来源。README、License/商业边界只对选定体验对象深读；Roadmap/Discussion、全部架构/安装文档及每位作者社交仍有未查范围。仅完整成功的来源查询推进本地基线，分页未完/不可访问/未核查分别记录。</li></ul><p>日档独立于 Research Runtime。中英文采用相同 O/A 编号、状态、来源及判断。本站页面的可用性由本轮发布回执与线上点击验收另行记录，源文件提交不代表已上线；若部署/核验失败，须在聊天明确报告。</p>',186)])])}const d=a(n,[["render",s]]);export{u as __pageData,d as default};
